const ALLOWED = ['application/pdf', 'image/png', 'image/jpeg', 'image/webp'];
const EXT = { 'application/pdf': '.pdf', 'image/png': '.png', 'image/jpeg': '.jpg', 'image/webp': '.webp' };
const MIN_IMAGE_BYTES = 20000; // skip tiny signature logos
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binary = item.binary || {};
  const sender = (item.json.from && item.json.from.text) || String(item.json.from || '');

  for (const key of Object.keys(binary)) {
    const file = binary[key];
    const type = (file.mimeType || '').toLowerCase();
    if (!ALLOWED.includes(type)) continue;

    if (type !== 'application/pdf') {
      const buf = await this.helpers.getBinaryDataBuffer(i, key);
      if (buf.length < MIN_IMAGE_BYTES) continue;
    }

    let name = file.fileName || 'attachment';
    if (!/\.(pdf|png|jpe?g|webp)$/i.test(name)) name += EXT[type];

    out.push({
      json: { sender, subject: item.json.subject || '', fileName: name },
      binary: { data: { ...file, fileName: name } },
    });
  }
}

return out;
